import AccessorArray = require( '@stdlib/array/base/accessor' );
import gnthIndexOf = require( './index' );


// TESTS //

// The function returns a number...
{
	var x = [ 1.0, 2.0, 3.0 ];

	gnthIndexOf( x.length, 1, 2.0, x, 1 ); // $ExpectType number
	gnthIndexOf( x.length, 1, 2.0, new AccessorArray( x ), 1 ); // $ExpectType number
}

// The compiler throws an error if the function is provided a first argument which is not a number...
{
	var x = [ 1.0, 2.0, 3.0 ];

	gnthIndexOf( '1', 1, 2.0, x, 1 ); // $ExpectError
	gnthIndexOf( true, 1, 2.0, x, 1 ); // $ExpectError
	gnthIndexOf( false, 1, 2.0, x, 1 ); // $ExpectError
	gnthIndexOf( null, 1, 2.0, x, 1 ); // $ExpectError
	gnthIndexOf( {}, 1, 2.0, x, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a number...
{
	var x = [ 1.0, 2.0, 3.0 ];

	gnthIndexOf( x.length, '1', 2.0, x, 1 ); // $ExpectError
	gnthIndexOf( x.length, true, 2.0, x, 1 ); // $ExpectError
	gnthIndexOf( x.length, false, 2.0, x, 1 ); // $ExpectError
	gnthIndexOf( x.length, null, 2.0, x, 1 ); // $ExpectError
	gnthIndexOf( x.length, {}, 2.0, x, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a fourth argument which is not a collection...
{
	gnthIndexOf( x.length, 1, 1.0, '1', 1 ); // $ExpectError
	gnthIndexOf( x.length, 1, 1.0, true, 1 ); // $ExpectError
	gnthIndexOf( x.length, 1, 1.0, false, 1 ); // $ExpectError
	gnthIndexOf( x.length, 1, 1.0, null, 1 ); // $ExpectError
	gnthIndexOf( x.length, 1, 1.0, {}, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a fifth argument which is not a number...
{
	var x = [ 1.0, 2.0, 3.0 ];

	gnthIndexOf( x.length, 1, 2.0, x, '1' ); // $ExpectError
	gnthIndexOf( x.length, 1, 2.0, x, true ); // $ExpectError
	gnthIndexOf( x.length, 1, 2.0, x, false ); // $ExpectError
	gnthIndexOf( x.length, 1, 2.0, x, null ); // $ExpectError
	gnthIndexOf( x.length, 1, 2.0, x, {} ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	gnthIndexOf(); // $ExpectError
	gnthIndexOf( 3, 1 ); // $ExpectError
	gnthIndexOf( 3, 1, 2.0 ); // $ExpectError
	gnthIndexOf( 3, 1, 2.0, [ 1.0, 2.0, 3.0 ] ); // $ExpectError
	gnthIndexOf( 3, 1, 2.0, [ 1.0, 2.0, 3.0 ], 1, 0 ); // $ExpectError
}

// Attached to main export is an `ndarray` method which returns a number...
{
	var x = [ 1.0, 2.0, 3.0 ];

	gnthIndexOf.ndarray( x.length, 1, 2.0, x, 1, 0 ); // $ExpectType number
	gnthIndexOf.ndarray( x.length, 1, 2.0, new AccessorArray( x ), 1, 0 ); // $ExpectType number
}

// The compiler throws an error if the `ndarray` method is provided a first argument which is not a number...
{
	var x = [ 1.0, 2.0, 3.0 ];

	gnthIndexOf.ndarray( '1', 1, 2.0, x, 1, 1 ); // $ExpectError
	gnthIndexOf.ndarray( true, 1, 2.0, x, 1, 1 ); // $ExpectError
	gnthIndexOf.ndarray( false, 1, 2.0, x, 1, 1 ); // $ExpectError
	gnthIndexOf.ndarray( null, 1, 2.0, x, 1, 1 ); // $ExpectError
	gnthIndexOf.ndarray( {}, 1, 2.0, x, 1, 1 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a second argument which is not a number...
{
	var x = [ 1.0, 2.0, 3.0 ];

	gnthIndexOf.ndarray( x.length, '1', 2.0, x, 1, 1 ); // $ExpectError
	gnthIndexOf.ndarray( x.length, true, 2.0, x, 1, 1 ); // $ExpectError
	gnthIndexOf.ndarray( x.length, false, 2.0, x, 1, 1 ); // $ExpectError
	gnthIndexOf.ndarray( x.length, null, 2.0, x, 1, 1 ); // $ExpectError
	gnthIndexOf.ndarray( x.length, {}, 2.0, x, 1, 1 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a fourth argument which is not a collection...
{
	gnthIndexOf.ndarray( x.length, 1, 1.0, '1', 1, 1 ); // $ExpectError
	gnthIndexOf.ndarray( x.length, 1, 1.0, true, 1, 1 ); // $ExpectError
	gnthIndexOf.ndarray( x.length, 1, 1.0, false, 1, 1 ); // $ExpectError
	gnthIndexOf.ndarray( x.length, 1, 1.0, null, 1, 1 ); // $ExpectError
	gnthIndexOf.ndarray( x.length, 1, 1.0, {}, 1, 1 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a fifth argument which is not a number...
{
	var x = [ 1.0, 2.0, 3.0 ];

	gnthIndexOf.ndarray( x.length, 1, 2.0, x, '1', 1 ); // $ExpectError
	gnthIndexOf.ndarray( x.length, 1, 2.0, x, true, 1 ); // $ExpectError
	gnthIndexOf.ndarray( x.length, 1, 2.0, x, false, 1 ); // $ExpectError
	gnthIndexOf.ndarray( x.length, 1, 2.0, x, null, 1 ); // $ExpectError
	gnthIndexOf.ndarray( x.length, 1, 2.0, x, {}, 1 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a sixth argument which is not a number...
{
	var x = [ 1.0, 2.0, 3.0 ];

	gnthIndexOf.ndarray( x.length, 1, 2.0, x, 1, '1' ); // $ExpectError
	gnthIndexOf.ndarray( x.length, 1, 2.0, x, 1, true ); // $ExpectError
	gnthIndexOf.ndarray( x.length, 1, 2.0, x, 1, false ); // $ExpectError
	gnthIndexOf.ndarray( x.length, 1, 2.0, x, 1, null ); // $ExpectError
	gnthIndexOf.ndarray( x.length, 1, 2.0, x, 1, {} ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided an unsupported number of arguments...
{
	gnthIndexOf.ndarray(); // $ExpectError
	gnthIndexOf.ndarray( 3, 1 ); // $ExpectError
	gnthIndexOf.ndarray( 3, 1, 2.0 ); // $ExpectError
	gnthIndexOf.ndarray( 3, 1, 2.0, [ 1.0, 2.0, 3.0 ] ); // $ExpectError
	gnthIndexOf.ndarray( 3, 1, 2.0, [ 1.0, 2.0, 3.0 ], 1 ); // $ExpectError
	gnthIndexOf.ndarray( 3, 1, 2.0, [ 1.0, 2.0, 3.0 ], 1, 0, 0 ); // $ExpectError
}
